INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(457356, 42710, 10686, '<td valign="top">Powerful image, I imagine this will cause a fuss.</td>', 'Powerful image, I imagine this will cause a fuss.', '2003-10-22 01:06:02.000000', NULL, 1),
(457365, 43081, 7969, '<td valign="top">I like the idea, but not sure about how carried it out.</td>', 'I like the idea, but not sure about how carried it out.', '2003-10-22 01:11:06.000000', NULL, 1),
(457366, 43162, 11073, '<td valign="top">great shot - would have done well in the lighting or shadow comps as well.  Like the shadow, and use of negative space.  Looks like the subject is looking at the camera - my only suggestion would be to have him look down or out into "emptiness" to help convey "alone" more (read: if he''s looking at you -  he''s not really all that alone with you there - but if he''s not looking at you - we the viewer have to give some willing suspension of disbelief that he is alone).  Nice work. 9.</td>', 'great shot - would have done well in the lighting or shadow comps as well.  Like the shadow, and use of negative space.  Looks like the subject is looking at the camera - my only suggestion would be to have him look down or out into "emptiness" to help convey "alone" more (read: if he''s looking at you -  he''s not really all that alone with you there - but if he''s not looking at you - we the viewer have to give some willing suspension of disbelief that he is alone).  Nice work. 9.', '2003-10-22 01:13:02.000000', NULL, 1),
(457368, 42501, 8816, '<td valign="top">This shot would have worked great with the couch in color and the rest of the picture in B&amp;W, give it a try, it would really emphasize the solitude of the couch in the forest, and the contrast of the couch and the forest.  Nice shot nontheless.  A tripod might have helped the sharpness a bit though! 7</td>', 'This shot would have worked great with the couch in color and the rest of the picture in B&W, give it a try, it would really emphasize the solitude of the couch in the forest, and the contrast of the couch and the forest.  Nice shot nontheless.  A tripod might have helped the sharpness a bit though! 7', '2003-10-22 01:13:57.000000', NULL, 1),
(457369, 42560, 8816, '<td valign="top">Love the motiong blur.  Especially effective in this photo! 8</td>', 'Love the motiong blur.  Especially effective in this photo! 8', '2003-10-22 01:14:32.000000', NULL, 1),
(457372, 43057, 255, '<td valign="top">wow, this is awesome. very moody and simple. 10</td>', 'wow, this is awesome. very moody and simple. 10', '2003-10-22 01:16:04.000000', NULL, 1),
(457373, 42710, 6668, '<td valign="top">This photo is extremely powerful, yet disturbing...wonderful idea (for a photo anyway, it''s not really a wonderful idea to point a gun to your head! :-) Love the use of negative space as well. 9</td>', 'This photo is extremely powerful, yet disturbing...wonderful idea (for a photo anyway, it''s not really a wonderful idea to point a gun to your head! :-) Love the use of negative space as well. 9', '2003-10-22 01:17:05.000000', NULL, 1),
(457375, 43093, 656, '<td valign="top">great colour and the person makes it special</td>', 'great colour and the person makes it special', '2003-10-22 01:17:56.000000', NULL, 1),
(457376, 43090, 7226, '<td valign="top">nice, very toy storyesk</td>', 'nice, very toy storyesk', '2003-10-22 01:18:46.000000', NULL, 1),
(457377, 43418, 6668, '<td valign="top">I understand the idea behind this photo..but visually it doesn''t do much for me, just not a very interesting image to look at for an extended period of time.</td>', 'I understand the idea behind this photo..but visually it doesn''t do much for me, just not a very interesting image to look at for an extended period of time.', '2003-10-22 01:18:51.000000', NULL, 1),
(457378, 43232, 10170, '<td valign="top">Excellent.  Almost looks like the boy is a black cardboard cut out.  Very well done indeed, and says "Alone" very nicely.</td>', 'Excellent.  Almost looks like the boy is a black cardboard cut out.  Very well done indeed, and says "Alone" very nicely.', '2003-10-22 01:19:04.000000', NULL, 1),
(457382, 42886, 675, '<td valign="top">wow this is amazing...10</td>', 'wow this is amazing...10', '2003-10-22 01:20:47.000000', NULL, 1),
(457383, 43119, 10170, '<td valign="top">Very nice use of light.  Would have done well in lighting or shadows as well I think.</td>', 'Very nice use of light.  Would have done well in lighting or shadows as well I think.', '2003-10-22 01:20:48.000000', NULL, 1),
(457384, 43119, 7226, '<td valign="top">nice setup.  it probably could have used some reflected or diffused light coming from above to better illuminate the eggs that are against the shadow.</td>', 'nice setup.  it probably could have used some reflected or diffused light coming from above to better illuminate the eggs that are against the shadow.', '2003-10-22 01:21:29.000000', NULL, 1),
(457386, 42883, 255, '<td valign="top">this is perfect. the color of the sky blending with the sunset--the stark simplicity of the silhouette--just gorgeous. 10</td>', 'this is perfect. the color of the sky blending with the sunset--the stark simplicity of the silhouette--just gorgeous. 10', '2003-10-22 01:21:37.000000', NULL, 1),
(457387, 43081, 12327, '<td valign="top">I like the idea, but I think I would have liked it better in BW.  Just a note,  it''s also racism when the white one gets pushed aside.</td>', 'I like the idea, but I think I would have liked it better in BW.  Just a note,  it''s also racism when the white one gets pushed aside.', '2003-10-22 01:21:43.000000', NULL, 1),
