INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(460140, 43297, 6458, '<td valign="top">Simple. Effective. The faded red against the blue of the water is just a great touch. Very evocative. Thank you. 10</td>', 'Simple. Effective. The faded red against the blue of the water is just a great touch. Very evocative. Thank you. 10', '2003-10-23 14:31:48.000000', NULL, 1),
(460141, 43331, 4008, '<td valign="top">great story told, good expression of despair, and well executed. Feeling of loneliness does not come across to me.</td>', 'great story told, good expression of despair, and well executed. Feeling of loneliness does not come across to me.', '2003-10-23 14:31:55.000000', NULL, 1),
(460142, 42824, 10145, '<td valign="top">I like this shot. One of my favorites so far....</td>', 'I like this shot. One of my favorites so far....', '2003-10-23 14:32:10.000000', NULL, 1),
(460143, 43297, 11114, '<td valign="top">ooooooooooooooooooooooooh   pretty!  The concept is a common one for this competition but the execution is simply breathtaking.  10</td>', 'ooooooooooooooooooooooooh   pretty!  The concept is a common one for this competition but the execution is simply breathtaking.  10', '2003-10-23 14:32:34.000000', NULL, 1),
