(460163, 42761, 12733, '<td valign="top">Pretty reflections off the piers and water.</td>', 'Pretty reflections off the piers and water.', '2003-10-23 14:45:54.000000', NULL, 1),
(460164, 42521, 4008, '<td valign="top">gorgeous, but no FEELING  of loneliness to me.</td>', 'gorgeous, but no FEELING  of loneliness to me.', '2003-10-23 14:46:07.000000', NULL, 1),
(460165, 42686, 10145, '<td valign="top">Very cool picture!</td>', 'Very cool picture!', '2003-10-23 14:46:40.000000', NULL, 1),
(460168, 43053, 12733, '<td valign="top">Nice composition, but the tree should be at least as sharply focused as the closest plants. More depth of field, or bring the tree in closer.</td>', 'Nice composition, but the tree should be at least as sharply focused as the closest plants. More depth of field, or bring the tree in closer.', '2003-10-23 14:48:26.000000', NULL, 1),
