(460171, 42883, 4008, '<td valign="top">gorgeous, but does not give me the feeling of loneliness</td>', 'gorgeous, but does not give me the feeling of loneliness', '2003-10-23 14:50:07.000000', NULL, 1),
(460172, 43365, 12733, '<td valign="top">The dark stairs and concrete wall make the bear sem lonelier than might otherwise be the case. Nice setup.</td>', 'The dark stairs and concrete wall make the bear sem lonelier than might otherwise be the case. Nice setup.', '2003-10-23 14:50:51.000000', NULL, 1),
