(460174, 43050, 11114, '<td valign="top">Where do you live that there''s snow already?</td>', 'Where do you live that there''s snow already?', '2003-10-23 14:54:13.000000', NULL, 1),
(460175, 43060, 4178, '<td valign="top">It''s greener than the pencil, anyway. (am I the 50th person to say that?)</td>', 'It''s greener than the pencil, anyway. (am I the 50th person to say that?)', '2003-10-23 14:55:20.000000', NULL, 1),
