INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(460558, 43357, 806, '<td valign="top">hmmm. "The new kid" title might have gone well with a group of children behind the subject out of the focal plane. However, this is a strong representation of alone in the image itself. Interesting composition, lines, textures.</td>', 'hmmm. "The new kid" title might have gone well with a group of children behind the subject out of the focal plane. However, this is a strong representation of alone in the image itself. Interesting composition, lines, textures.', '2003-10-23 22:09:43.000000', NULL, 1),
(460559, 42686, 13493, '<td valign="top">maybe better in the lighting challenge</td>', 'maybe better in the lighting challenge', '2003-10-23 22:10:00.000000', NULL, 1),
(460560, 42735, 13493, '<td valign="top">sad. but meets the challenge. nice color</td>', 'sad. but meets the challenge. nice color', '2003-10-23 22:10:57.000000', NULL, 1),
(460562, 43297, 806, '<td valign="top">utter stillness.. like time itself has stopped.<br/>beautiful how the (assuming:) slow shutter speed? has created tension around the edge of the leave. decent use of negative space.</td>', 'utter stillness.. like time itself has stopped.beautiful how the (assuming:) slow shutter speed? has created tension around the edge of the leave. decent use of negative space.', '2003-10-23 22:11:02.000000', NULL, 1),
(460564, 43030, 13493, '<td valign="top">nice color. i''m sure you had to wait awhile to get this one. meets challenge</td>', 'nice color. i''m sure you had to wait awhile to get this one. meets challenge', '2003-10-23 22:11:36.000000', NULL, 1),
